import{_ as e,o as t,a as s,b as i,f as o}from"./index-DOOEPxDx.js";const d={class:"min-h-screen w-full bg-primary text-white px-6 pt-20 pb-12 md:pt-32"},c={__name:"FAQ",setup(n){return t(()=>{window.scrollTo(0,0)}),(r,a)=>(i(),s("section",d,[...a[0]||(a[0]=[o('<div class="max-w-4xl mx-auto text-center mb-16" data-v-acd11b6e><h1 class="text-4xl md:text-5xl font-extrabold mb-4 leading-tight" data-v-acd11b6e> Cadena Bitcoin FAQ </h1><p class="text-tertiary text-lg" data-v-acd11b6e>Common questions about how Cadena works, financial terms, and user security</p></div><div class="max-w-5xl mx-auto space-y-14 text-white/90 text-lg leading-relaxed" data-v-acd11b6e><div class="text-tertiary space-y-4" data-v-acd11b6e><p data-v-acd11b6e> Cadena Bitcoin’s product enables peer-to-peer lending and borrowing using Bitcoin as collateral through Discreet Log Contracts (DLCs). Below, we answer common questions about its use cases, how it works, financial terms, and security. </p><p class="italic" data-v-acd11b6e> For more technical details, check out the Technical Overview, or explore our open-source resources on GitHub. </p></div><div id="use-case" data-v-acd11b6e><h2 class="text-2xl md:text-3xl font-bold mb-4" data-v-acd11b6e>1. Use Case for Cadena’s Product?</h2><p class="mb-4" data-v-acd11b6e> Cadena Bitcoin lets you use Bitcoin flexibly—whether you want to grow your Bitcoin holdings, access fiat without losing Bitcoin exposure, or generate fiat returns secured by Bitcoin. Here’s how it works for two types of users: </p><p class="font-semibold mb-2" data-v-acd11b6e>Bob (Borrower)</p><p class="mb-4" data-v-acd11b6e> Bob wants more Bitcoin exposure without selling his stash. He uses his Bitcoin as collateral to borrow additional Bitcoin via Cadena, allowing him to HODL more. Alternatively, if Bob needs fiat, he can borrow Bitcoin, sell it for fiat, and remain protected if Bitcoin’s price rises. </p><p class="font-semibold mb-2" data-v-acd11b6e>Alice (Investor)</p><p class="mb-4" data-v-acd11b6e> Alice seeks a high risk-adjusted fiat return, secured by Bitcoin collateral. She’s okay with the risk of losing fiat if Bitcoin’s value drops. If Bitcoin falls significantly, Alice keeps the collateral, boosting her Bitcoin holdings. </p><p class="italic text-tertiary" data-v-acd11b6e>Check out our video walking through the life cycle of a Cadena loan!</p></div><div id="how-it-works" data-v-acd11b6e><h2 class="text-2xl md:text-3xl font-bold mb-4" data-v-acd11b6e>2. How Does it Work?</h2><p class="mb-3" data-v-acd11b6e>Cadena Bitcoin is a decentralized lending and borrowing product where users lock Bitcoin collateral in a DLC to facilitate loans. Here’s a breakdown of the key actions:</p><p class="font-semibold mb-1" data-v-acd11b6e>Posting an Offer</p><p class="mb-3" data-v-acd11b6e> A user (Initiator) posts an offer on Cadena Bitcoin, locking collateral and specifying interest rate. Terms like loan size (0.1 Bitcoin), duration (1 month), and currency (USD) are fixed in the current product. </p><p class="font-semibold mb-1" data-v-acd11b6e>Accepting an Offer</p><p class="mb-3" data-v-acd11b6e> Another user (Peer) accepts the offer, locking in their collateral and forming a contract. </p><p class="font-semibold mb-1" data-v-acd11b6e>Funding Transaction</p><p class="mb-3" data-v-acd11b6e> The on-chain DLC holds users’ collateral, provides change, and covers Cadena Bitcoin’s service fee. </p><p class="font-semibold mb-1" data-v-acd11b6e>Contract Execution</p><p data-v-acd11b6e> At maturity, the Oracle’s attestation determines the contract outcome. A single Contract Execution Transaction (CET) is broadcast, splitting the locked collateral based on the BTC/USD open and closing price. </p></div><div id="financial-terms" data-v-acd11b6e><h2 class="text-2xl md:text-3xl font-bold mb-4" data-v-acd11b6e>3. What Are the Financial Terms (MVP)?</h2><p class="font-semibold mb-1" data-v-acd11b6e>Term</p><p class="mb-3" data-v-acd11b6e> Every Cadena Bitcoin contract has a duration of 30 days, starting when the contract is accepted. The actual duration may extend slightly to align with the next available Oracle attestation. </p><p class="font-semibold mb-1" data-v-acd11b6e>Interest</p><p class="mb-3" data-v-acd11b6e> Simple interest, 30/360 day count convention (like USD Treasury Bills). No compounding. </p><p class="mb-3 italic text-tertiary" data-v-acd11b6e> Note: The 360-day year slightly understates the effective rate vs. a 365-day year. </p><ul class="list-disc list-inside space-y-2" data-v-acd11b6e><li data-v-acd11b6e>Contract Sum: 0.1 BTC</li><li data-v-acd11b6e>Base Loan: 80% of the contract sum (0.08 BTC)</li><li data-v-acd11b6e>Lender Contribution: <code class="bg-white/10 px-1 rounded" data-v-acd11b6e>free_loan = base_loan / (1.0 + interest / 100)</code></li><li data-v-acd11b6e>Borrower Contribution: 0.1 BTC + 0.50% fee − lender amount</li><li data-v-acd11b6e>BTC/USD O/C Ratio: Open to Close price ratio determines final split</li></ul></div><div id="security" data-v-acd11b6e><h2 class="text-2xl md:text-3xl font-bold mb-4" data-v-acd11b6e>4. Security</h2><p class="mb-3" data-v-acd11b6e>Cadena Bitcoin prioritizes self-sovereignty, decentralization, and Bitcoin’s core security principles:</p><ul class="list-disc list-inside space-y-2" data-v-acd11b6e><li data-v-acd11b6e><strong data-v-acd11b6e>Your Keys, Your Coins:</strong> You control your keys. Cadena never touches them.</li><li data-v-acd11b6e><strong data-v-acd11b6e>User Responsibility:</strong> Your private data is yours to protect.</li></ul><p class="font-semibold mt-6 mb-1" data-v-acd11b6e>Identification and Access</p><ul class="list-disc list-inside space-y-2" data-v-acd11b6e><li data-v-acd11b6e><strong data-v-acd11b6e>Email Address:</strong> Your Cadena ID. No recovery if forgotten.</li><li data-v-acd11b6e><strong data-v-acd11b6e>Seed Phrase:</strong> 12-word mnemonic from Signer App, encrypted with your password.</li></ul><p class="italic text-tertiary mt-3" data-v-acd11b6e>Important: Backup your keys. You control funds even if Cadena disappears.</p><p class="text-red-400 font-semibold mt-2" data-v-acd11b6e>Warning: Never share your seed phrase. We’ll never ask for it.</p><ul class="list-disc list-inside space-y-2 mt-4" data-v-acd11b6e><li data-v-acd11b6e><strong data-v-acd11b6e>Password:</strong> Used across Cadena + Signer App to unlock your phrase.</li></ul><p class="text-red-400 font-semibold mt-2" data-v-acd11b6e>Warning: Don’t reuse your email password. Leaks = lost funds.</p></div><div class="text-center pt-8 border-t border-secondary/30" data-v-acd11b6e><p class="text-white/80" data-v-acd11b6e> For more details, check our <a href="#" class="underline hover:text-white" data-v-acd11b6e>Technical Overview</a> or explore <a href="#" class="underline hover:text-white" data-v-acd11b6e> our GitHub</a>. </p></div></div>',2)])]))}},b=e(c,[["__scopeId","data-v-acd11b6e"]]);export{b as default};
